C-Header
Der Header enthält Größen und alle Werte als Konstanten sowie die Funktion &lt;PRÄFIX&gt;_Init, die daraus ein fertiges Netz baut. Das Präfix (hier XOR) steht vor jedem Namen, damit mehrere Netze in einem Programm Platz haben. WEIGHTS[n][m] heißt: Neuron n dieses Layers, Gewicht für Input m.
// Generated by neural_network (insy-nn v1). Do not edit.
// Activation: sigmoid
#ifndef XOR_NET_H
#define XOR_NET_H

#include "neural_network.h"

#define XOR_INPUT_SIZE 2
#define XOR_LAYER_COUNT 2

static const int XOR_LAYER_SIZES[XOR_LAYER_COUNT] = {2, 1};

// Layer 1: 2 neurons x 2 inputs
static const double XOR_L1_WEIGHTS[2][2] = {
    {5.900521966319981, -5.914256815253622},
    {-5.421024708486351, 5.135707632445938},
};
static const double XOR_L1_BIASES[2] = {-3.357581665610364, -2.859692553869736};

// Layer 2: 1 neurons x 2 inputs
static const double XOR_L2_WEIGHTS[1][2] = {
    {8.158894259030141, 8.307855908650177},
};
static const double XOR_L2_BIASES[1] = {-4.0624992872092545};

// Storage for the network that XOR_Init builds; no heap memory needed
static Neuron XOR_L1_NEURONS[2];
static Neuron XOR_L2_NEURONS[1];
static Layer XOR_LAYERS[XOR_LAYER_COUNT];

/// Builds the network from the constants above.
/// The weights stay in the constant arrays: never pass it to NetworkFree.
static inline void XOR_Init (Network *network)
{
    for (int n = 0; n &lt; 2; n++)
    {
        XOR_L1_NEURONS[n] = (Neuron){.weights = XOR_L1_WEIGHTS[n], .bias = XOR_L1_BIASES[n], .inputCount = 2};
    }
    XOR_LAYERS[0] = (Layer){.neurons = XOR_L1_NEURONS, .neuronCount = 2, .inputCount = 2};
    for (int n = 0; n &lt; 1; n++)
    {
        XOR_L2_NEURONS[n] = (Neuron){.weights = XOR_L2_WEIGHTS[n], .bias = XOR_L2_BIASES[n], .inputCount = 2};
    }
    XOR_LAYERS[1] = (Layer){.neurons = XOR_L2_NEURONS, .neuronCount = 1, .inputCount = 2};
    *network = (Network){.layers = XOR_LAYERS, .layerCount = XOR_LAYER_COUNT, .inputSize = XOR_INPUT_SIZE};
}

#endif // XOR_NET_H
Die Typen Neuron, Layer und Network kommen aus neural_network.h der C-Version. Die Init-Funktion kopiert keine Gewichte, sondern lässt jedes Neuron auf seine Zeile im konstanten Array zeigen. Sie braucht weder malloc noch eine Datei, wie es auf einem Mikrocontroller nötig ist.

Wichtige Codeteile

Neuron: Forward und Update
def activate(self, inputs: FloatArray) -&gt; float:
    self.inputs = inputs
    z = float(np.dot(self.weights, inputs)) + self.bias
    self.output = self._activation_fn(z)
    return self.output

def update_weights(self, delta: float, learning_rate: float) -&gt; None:
    # dJ/dw_i = dJ/dz * dz/dw_i = delta * x_i
    self.weights -= learning_rate * delta * self.inputs


Layer: Backpropagation
Das ist die Umsetzung von Delta und Gradient für einen Layer:
def backward(self, errors: FloatArray, learning_rate: float) -&gt; FloatArray:
    previous_errors = np.zeros(self.input_size)

    for neuron, error in zip(self.neurons, errors, strict=True):
        # dJ/dz = dJ/da * da/dz
        delta = error * neuron.activate_derivative()

        # dz/dx_i = w_i; must use the weights from the forward pass,
        # so this happens before the update below
        previous_errors += delta * neuron.weights

        neuron.update_weights(delta, learning_rate)
        neuron.update_bias(delta, learning_rate)

    return previous_errors
Die C#-Version rechnet mit einfachen Schleifen statt mit numpy, der Ablauf ist derselbe:
public double[] Backward (double[] errors, double learningRate)
{
    double[] previousErrors = new double[InputSize];

    for (int n = 0; n &lt; Neurons.Length; n++)
    {
        Neuron neuron = Neurons[n];

        // dJ/dz = dJ/da * da/dz
        double delta = errors[n] * neuron.ActivateDerivative();

        // dz/dx_i = w_i; must use the weights from the forward pass,
        // so this happens before the update below
        for (int i = 0; i &lt; InputSize; i++)
        {
            previousErrors[i] += delta * neuron.Weights[i];
        }

        neuron.UpdateWeights(delta, learningRate);
        neuron.UpdateBias(delta, learningRate);
    }

    return previousErrors;
}


Netz: ein Trainingsschritt
def train(self, inputs: ArrayLike, targets: ArrayLike) -&gt; float:
    expected = np.asarray(targets, dtype=np.float64)
    outputs = self.predict(inputs)

    # dJ/dy_hat for J = 1/2 * (y_hat - y)^2
    errors = outputs - expected
    for layer in reversed(self.layers):
        errors = layer.backward(errors, self.learning_rate)

    return 0.5 * float(np.sum((outputs - expected) ** 2))
